import React, { useEffect, useRef, memo } from 'react';

// ── Symbol mapping: our coin symbols → TradingView BINANCE pairs ───────────
const TV_SYMBOL_MAP = {
  BTC:   'BINANCE:BTCUSDT',
  ETH:   'BINANCE:ETHUSDT',
  SOL:   'BINANCE:SOLUSDT',
  BNB:   'BINANCE:BNBUSDT',
  XRP:   'BINANCE:XRPUSDT',
  DOGE:  'BINANCE:DOGEUSDT',
  ADA:   'BINANCE:ADAUSDT',
  AVAX:  'BINANCE:AVAXUSDT',
  DOT:   'BINANCE:DOTUSDT',
  POL:   'BINANCE:MATICUSDT',
  MATIC: 'BINANCE:MATICUSDT',
  LINK:  'BINANCE:LINKUSDT',
  UNI:   'BINANCE:UNIUSDT',
  ATOM:  'BINANCE:ATOMUSDT',
  LTC:   'BINANCE:LTCUSDT',
  NEAR:  'BINANCE:NEARUSDT',
  APT:   'BINANCE:APTUSDT',
  ARB:   'BINANCE:ARBUSDT',
  OP:    'BINANCE:OPUSDT',
  TON:   'BINANCE:TONUSDT',
  SHIB:  'BINANCE:SHIBUSDT',
  IMX:   'BINANCE:IMXUSDT',
  BLUR:  'BINANCE:BLURUSDT',
  SEI:   'BINANCE:SEIUSDT',
  SUI:   'BINANCE:SUIUSDT',
  ALGO:  'BINANCE:ALGOUSDT',
  FIL:   'BINANCE:FILUSDT',
  XMR:   'BINANCE:XMRUSDT',
  AAVE:  'BINANCE:AAVEUSDT',
  MKR:   'BINANCE:MKRUSDT',
  CRV:   'BINANCE:CRVUSDT',
  LDO:   'BINANCE:LDOUSDT',
  DYDX:  'BINANCE:DYDXUSDT',
  INJ:   'BINANCE:INJUSDT',
  STX:   'BINANCE:STXUSDT',
  TIA:   'BINANCE:TIAUSDT',
  WIF:   'BINANCE:WIFUSDT',
  PEPE:  'BINANCE:PEPEUSDT',
  BONK:  'BINANCE:BONKUSDT',
  FLOKI: 'BINANCE:FLOKIUSDT',
  TAO:   'BINANCE:TAOUSDT',
  KAS:   'BINANCE:KASUSDT',
  PENDLE:'BINANCE:PENDLEUSDT',
  RNDR:  'BINANCE:RNDRUSDT',
  FET:   'BINANCE:FETUSDT',
  WLD:   'BINANCE:WLDUSDT',
  JUP:   'BINANCE:JUPUSDT',
  JTO:   'BINANCE:JTOUSDT',
  PYTH:  'BINANCE:PYTHUSDT',
  AR:    'BINANCE:ARUSDT',
  GALA:  'BINANCE:GALAUSDT',
  AXS:   'BINANCE:AXSUSDT',
  SAND:  'BINANCE:SANDUSDT',
  MANA:  'BINANCE:MANAUSDT',
  CAKE:  'BINANCE:CAKEUSDT',
  '1INCH':'BINANCE:1INCHUSDT',
  LRC:   'BINANCE:LRCUSDT',
  BAT:   'BINANCE:BATUSDT',
  CHZ:   'BINANCE:CHZUSDT',
  ZIL:   'BINANCE:ZILUSDT',
  ENJ:   'BINANCE:ENJUSDT',
  VET:   'BINANCE:VETUSDT',
  THETA: 'BINANCE:THETAUSDT',
  XTZ:   'BINANCE:XTZUSDT',
  NEO:   'BINANCE:NEOUSDT',
  QTUM:  'BINANCE:QTUMUSDT',
  ICX:   'BINANCE:ICXUSDT',
  EGLD:  'BINANCE:EGLDUSDT',
  ICP:   'BINANCE:ICPUSDT',
  ETC:   'BINANCE:ETCUSDT',
  XLM:   'BINANCE:XLMUSDT',
  TRX:   'BINANCE:TRXUSDT',
  SNX:   'BINANCE:SNXUSDT',
  COMP:  'BINANCE:COMPUSDT',
  YFI:   'BINANCE:YFIUSDT',
  BAL:   'BINANCE:BALUSDT',
  OKB:   'BINANCE:OKBUSDT',
  STORJ: 'BINANCE:STORJUSDT',
  NMR:   'BINANCE:NMRUSDT',
  OCEAN: 'BINANCE:OCEANUSDT',
  ACH:   'BINANCE:ARUSDT',
};

const getTVSymbol = (symbol) => TV_SYMBOL_MAP[symbol] || `BINANCE:${symbol}USDT`;

/**
 * ── TradingView Widget Component ──────────────────────────────────────────
 * Uses the external-embedding script method which is more robust for React environments.
 */
function TradingViewChart({ symbol = 'BTC' }) {
  const containerRef = useRef(null);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    // Clear any previous widget content
    container.innerHTML = '';

    // Create the script for the advanced chart widget
    const script = document.createElement('script');
    script.src = 'https://s3.tradingview.com/external-embedding/embed-widget-advanced-chart.js';
    script.type = 'text/javascript';
    script.async = true;

    // Config for the widget
    const config = {
      "width": "100%",
      "height": "100%",
      "symbol": getTVSymbol(symbol),
      "interval": "D",
      "timezone": "Etc/UTC",
      "theme": "dark",
      "style": "1",
      "locale": "en",
      "enable_publishing": false,
      "allow_symbol_change": true,
      "calendar": false,
      "support_host": "https://www.tradingview.com"
    };

    script.innerHTML = JSON.stringify(config);

    // Append script to our container
    container.appendChild(script);

    return () => {
      if (container) {
        container.innerHTML = '';
      }
    };
  }, [symbol]);

  return (
    <div 
      className="tradingview-widget-container"
      ref={containerRef}
      style={{ 
        width: '100%', 
        height: '100%', 
        minHeight: '600px',
        background: '#04070d'
      }}
    >
      <div className="tradingview-widget-container__widget" style={{ height: 'calc(100% - 32px)', width: '100%' }}></div>
    </div>
  );
}

export default memo(TradingViewChart);
